// Decides whether the assistant may send one WhatsApp message to a patient.
//
// Rules (WhatsApp Business Platform / Cloud API):
// - Opt-in: the business may only message a user who opted in. Checked first, for every message type.
// - Templates: pre-approved templates may be sent at any time once opted in.
// - Free-form text: only inside the customer service window, which is 24 hours
//   from the user's most recent inbound message. Outside it, Meta rejects the send.
// - Webhook `timestamp` is a Unix time in whole seconds, sent as a string.
//   It is not in milliseconds, so it must be multiplied by 1000 before use.

const WINDOW_MS = 24 * 60 * 60 * 1000;

export function decideWhatsApp(message, now) {
  const block = (reason) => ({ allowed: false, reason });

  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    return block('invalid_clock');
  }

  const contact = message?.contact;
  if (contact?.optedIn !== true) {
    return block('not_opted_in');
  }

  if (message.type === 'template') {
    return { allowed: true, reason: null };
  }

  if (message.type !== 'text') {
    return block('unknown_message_type');
  }

  const raw = contact.lastInboundTimestamp;
  if (raw === null || raw === undefined) {
    return block('no_inbound_message');
  }
  if (typeof raw !== 'string' || !/^\d+$/.test(raw)) {
    return block('invalid_inbound_timestamp');
  }

  const lastInboundMs = Number(raw) * 1000;
  if (!Number.isSafeInteger(lastInboundMs)) {
    return block('invalid_inbound_timestamp');
  }

  const nowMs = now.getTime();
  if (lastInboundMs > nowMs) {
    return block('inbound_timestamp_in_future');
  }

  if (nowMs - lastInboundMs >= WINDOW_MS) {
    return block('service_window_closed');
  }

  return { allowed: true, reason: null };
}

input.command:
node --input-type=module -e "
import { decideWhatsApp as d } from './bot.mjs';
const ok = (m, n) => JSON.stringify(d(m, n));
const T = '1767272400'; // 2026-01-01T13:00:00Z
const at = (ms) => new Date(Date.parse('2026-01-01T13:00:00Z') + ms);
const H = 3600e3;
const c = (lit, ts = T) => ({ optedIn: lit, lastInboundTimestamp: ts });
const cases = [
  ['text in window', { type:'text', contact:c(true) }, at(1*H), 'allowed'],
  ['text 23h59m59s', { type:'text', contact:c(true) }, at(24*H-1000), 'allowed'],
  ['text at exactly 24h', { type:'text', contact:c(true) }, at(24*H), 'service_window_closed'],
  ['text after 3 days', { type:'text', contact:c(true) }, at(72*H), 'service_window_closed'],
  ['text no inbound', { type:'text', contact:c(true, null) }, at(0), 'no_inbound_message'],
  ['text not opted in', { type:'text', contact:c(false) }, at(H), 'not_opted_in'],
  ['template not opted in', { type:'template', contact:c(false, null) }, at(0), 'not_opted_in'],
  ['template no inbound', { type:'template', contact:c(true, null) }, at(0), 'allowed'],
  ['template after window', { type:'template', contact:c(true) }, at(100*H), 'allowed'],
  ['text ms-looking ts is in future', { type:'text', contact:c(true, '1767272400000') }, at(H), 'inbound_timestamp_in_future'],
  ['text numeric ts', { type:'text', contact:c(true, 1767272400) }, at(H), 'invalid_inbound_timestamp'],
  ['text garbage ts', { type:'text', contact:c(true, '12a') }, at(H), 'invalid_inbound_timestamp'],
  ['text future', { type:'text', contact:c(true) }, at(-5000), 'inbound_timestamp_in_future'],
  ['bad type', { type:'image', contact:c(true) }, at(H), 'unknown_message_type'],
  ['bad clock', { type:'text', contact:c(true) }, new Date('x'), 'invalid_clock'],
];
let fail = 0;
for (const [name, m, n, exp] of cases) {
  const r = d(m, n);
  const got = r.allowed ? 'allowed' : r.reason;
  const pass = got === exp && (r.allowed ? r.reason === null : typeof r.reason === 'string');
  if (!pass) fail++;
  console.log(pass ? 'PASS' : 'FAIL', name, '->', ok(m, n));
}
console.log(fail ? fail + ' FAILED' : 'all ' + cases.length + ' passed');
"

